arguments.command:
OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=2 python -u -c "import warnings; import numpy as np; import pandas as pd; from sklearn.base import clone; from sklearn.ensemble import ExtraTreesRegressor, RandomForestRegressor; from sklearn.model_selection import RepeatedKFold; from sklearn.pipeline import make_pipeline; from sklearn.preprocessing import StandardScaler; from sklearn.svm import SVR; from sklearn.gaussian_process import GaussianProcessRegressor; from sklearn.gaussian_process.kernels import ConstantKernel, Matern, RBF, WhiteKernel; from catboost import CatBoostRegressor
warnings.filterwarnings('ignore'); a=pd.read_csv('b3_fatigue_train.csv'); b=pd.read_csv('b3_fatigue_pool.csv'); a=a[a.CT==930].reset_index(drop=True); b=b[b.CT==930].reset_index(drop=True); features=['Ct','DT','Dt','QmT','TT','C','Si','Mn','P','S','Ni','Cr','Cu','Mo','RedRatio','dA','dB','dC']; X=a[features]; y=a.target.to_numpy(); P=b[features]
models={'rf':RandomForestRegressor(n_estimators=500,max_features=0.8,random_state=12,n_jobs=2),'extra':ExtraTreesRegressor(n_estimators=500,random_state=12,n_jobs=2),'svr_100':make_pipeline(StandardScaler(),SVR(C=100,gamma=0.01,epsilon=10)),'svr_1000':make_pipeline(StandardScaler(),SVR(C=1000,gamma=0.02,epsilon=10)),'gp_rbf':make_pipeline(StandardScaler(),GaussianProcessRegressor(kernel=ConstantKernel(1,(.01,100))*RBF(np.ones(len(features)),(.1,100))+WhiteKernel(.1,(.001,2)),normalize_y=True,n_restarts_optimizer=0,random_state=12)),'gp_matern':make_pipeline(StandardScaler(),GaussianProcessRegressor(kernel=ConstantKernel(1,(.01,100))*Matern(np.ones(len(features)),(.1,100),nu=1.5)+WhiteKernel(.1,(.001,2)),normalize_y=True,n_restarts_optimizer=0,random_state=12)),'cat3':CatBoostRegressor(iterations=800,depth=3,learning_rate=0.03,l2_leaf_reg=5,random_seed=12,verbose=False,allow_writing_files=False,thread_count=2)}
splits=list(RepeatedKFold(n_splits=5,n_repeats=5,random_state=510).split(X)); preds=pd.DataFrame({'id':b.candidate_id}); errs={}
for name,t in models.items():
 oof=np.zeros((5,len(y)))
 for k,(tr,va) in enumerate(splits):
  m=clone(t).fit(X.iloc[tr],y[tr]); oof[k//5,va]=m.predict(X.iloc[va])
 e=oof-y; errs[name]=e; print(name,'RMSE',round(np.sqrt(np.mean(e**2)),2),'MAE',round(np.mean(np.abs(e)),2),flush=True); m=clone(t).fit(X,y); preds[name]=m.predict(P)
 if name.startswith('gp'): print('kernel',m[-1].kernel_,flush=True)
 print(preds[['id',name]].sort_values(name,ascending=False).round(1).to_string(index=False),flush=True)
print('ALL_LOCAL'); print(preds.round(1).to_string(index=False))"

